const AUDIO_LISTENING_FULL = "https://huonghsk.com/audio/dethi-hsk1/listening-full.mp3";

window.requestSwitchReading = function(targetQNum){
  if(window.submitted || window.currentPage === "reading"){
    if(window.switchPage) window.switchPage("reading", targetQNum);
    return;
  }
  
  var mTitle = document.querySelector("#mTitle");
  var mText = document.querySelector("#mText");
  var mList = document.querySelector("#mList");
  var mNo = document.querySelector("#mNo");
  var mYes = document.querySelector("#mYes");
  var modal = document.querySelector("#modal");
  
  if(mTitle) mTitle.innerHTML = "⚠️ Cảnh báo: Kết thúc Phần Nghe!";
  if(mText) mText.innerHTML = "Sau khi chuyển sang <b>Phần Đọc (Câu 21–40)</b>, bạn sẽ <b>KHÔNG THỂ QUAY LẠI</b> làm hoặc sửa đáp án <b>Phần Nghe (Câu 1–20)</b> được nữa.";
  
  if(mList) {
    mList.style.display = "block";
    mList.innerHTML = "<div class='switch-warn-box'>• 🛑 <b>Không thể quay lại</b> sửa 20 câu Nghe đầu.<br>• 🎧 <b>File nghe sẽ tự động dừng.</b><br>• 📖 <b>Bắt đầu làm ngay 20 câu Phần Đọc.</b></div>";
  }
  
  if(mNo) {
    mNo.textContent = "Quay lại làm tiếp Phần Nghe";
    mNo.className = "btn";
    mNo.onclick = function(){
      if(window.closeModal) window.closeModal();
    };
  }
  
  if(mYes) {
    mYes.textContent = "Đồng ý chuyển sang Phần Đọc →";
    mYes.className = "btn primary";
    mYes.onclick = function(){
      if(window.closeModal) window.closeModal();
      if(window.switchPage) window.switchPage("reading", targetQNum);
    };
  }
  
  if(modal) modal.classList.add("on");
};

